import{_ as i,l as n,o as e,c as l,v as t,p as s,x as r,d,i as c,S as B}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"CBDC","description":"","frontmatter":{"title":"CBDC","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cbdc.md","filePath":"econ/cbdc.md","lastUpdated":1789023840000}'),C={name:"econ/cbdc.md"};function p(h,a,D,E,_,m){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="cbdc" tabindex="-1">CBDC <a class="header-anchor" href="#cbdc" aria-label="Permalink to &quot;CBDC&quot;">​</a></h1><div class="epigraph"><p>央行数字货币是公共部门的新负债科目：可以像现金，也可以像付息储备的零售版。设计决定它挤的是存款、现金还是 MMF。</p><footer>—— 对照 BIS 对 CBDC 的综述；Brunnermeier and Niepelt 对公共货币与私人货币共存的讨论</footer></div><p><a href="/econ/repo-mmf">上一课</a>把私人短债生态钉住。缺口是：若央行直接给公众一个数字账户，中介和地板工具怎么改。本课钉 CBDC 的宏观逻辑，美元主导下一课才出国界。不写某试点的 UI。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CBDC 可以是现金的替代（匿名、不计息）或存款的替代（账户、或付息）。后者在危机时提供「公共安全账户」，可能加速银行挤兑（DD 加上一个永远不挤的选项）。若计息，它还与准备金、ON RRP 抢利率走廊。缺口是用已有的中介与主导语言选设计，而不是「要不要数字化」的口号。</p><p><span class="marginnote">Andolfatto；Keister and Sanches 讨论 CBDC 与银行信贷。Piazzesi and Schneider 对支付与中介。中国 e-CNY 是零售支付试点，不等于计息 CBDC 宏观。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个旋钮：准入（批发 vs 零售）、报酬（零利率 vs 政策利率附近）、持有上限。宏观映射：零售不计息 ≈ 现金；零售计息 ≈ 把 HANK 里的安全资产供给外生扩大；批发 CBDC ≈ 给非银一个储备账户。与财政主导：付息 CBDC 是更多名义公共债。与影子：若 CBDC 替代 MMF，ON RRP 需求下降。</p>',8)),(e(),s(B,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASH%5B%22%E7%8E%B0%E9%87%91%E5%9E%8B%22%5D%20--%3E%20PAY%5B%22%E6%94%AF%E4%BB%98%22%5D%0A%20%20DEP%5B%22%E5%AD%98%E6%AC%BE%E5%9E%8B%22%5D%20--%3E%20RUN%5B%22%E6%8C%A4%E5%85%91%E9%80%89%E9%A1%B9%22%5D%0A%20%20INT%5B%22%E8%AE%A1%E6%81%AF%22%5D%20--%3E%20FLOOR%5B%22%E8%B5%B0%E5%BB%8A%E4%B8%8E%E4%B8%AD%E4%BB%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>银行负债若被 CBDC 置换，除非央行把资金贷回银行，信贷供给要走新的 \\(\\phi\\)。批发 CBDC 改变谁能持有央行负债，等于重划「银行」边界。匿名性与 AML 是微观约束，会限制现金型能做多大。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不预测发行时间表，不把 CBDC 写成已替代美元。下一课国际：美元负债网络比零售 CBDC 更硬。不讨论钱包密码学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CBDC 的宏观效应取决于它替代现金、存款还是货基。</li><li>计息零售 CBDC 是新的挤兑与走廊工具。</li><li>出处：BIS CBDC 综述；Brunnermeier–Niepelt；Keister–Sanches。</li></ul>',6))])}const f=i(C,[["render",p]]);export{u as __pageData,f as default};
